function s(v) { return String(v == null ? '' : v).trim(); }
function nz(x) { return s(x).toLowerCase().replace(/[^a-z0-9@.]/g, ''); }
const WEEK_CAP = 5;    // user rule 2026-09-10: max 5 new deals per investor inbox per week
const DAY_CAP = 2;     // never stack more than 2 on one inbox in one morning
const OWNER_CAP = 20;  // per mailbox per weekday, ~ the real pace of ~76/day across four
const TODAY = '2026-09-10';

const hdr = (($('GET header').first().json.values || [[]])[0] || []).map(s);
const col = hdr.indexOf('next_due');
if (col < 0) { throw new Error('ABORT: next_due column not found in PIPELINE header: ' + JSON.stringify(hdr)); }
function colLetter(i) { let n = i + 1, out = ''; while (n > 0) { const m = (n - 1) % 26; out = String.fromCharCode(65 + m) + out; n = Math.floor((n - 1) / 26); } return out; }
const L = colLetter(col);

const stRaw = $('Read STARTUPS').all().map(function (i) { return i.json; });
const pipe = $input.all().map(function (i) { return i.json; });
if (pipe.length < 500) { throw new Error('ABORT: PIPELINE only ' + pipe.length); }
const active = {};
for (const r of stRaw) { if (s(r.startup) && s(r.active).toLowerCase() === 'yes') { active[s(r.startup)] = s(r.owner); } }

function parseDate(v) {
  const t = s(v); if (!t) { return null; }
  let m = t.match(/^(\d{4})-(\d{2})-(\d{2})/); if (m) { return m[1] + '-' + m[2] + '-' + m[3]; }
  m = t.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{2,4})/);
  if (m) { let y = +m[3]; if (y < 100) { y += 2000; } return y + '-' + ('0' + m[2]).slice(-2) + '-' + ('0' + m[1]).slice(-2); }
  const d = new Date(t); return isNaN(d.getTime()) ? null : d.toISOString().slice(0, 10);
}
function who(p) { const e = s(p.email).split(/[,;\s]+/)[0].toLowerCase(); return e ? e : 'name:' + nz(p.investor); }

// deals already sent this calendar week (Mon 7 Sep onward) count against the cap
const sentThisWeek = {};
for (const p of pipe) {
  if (s(p.deal_shared).toLowerCase() !== 'yes') { continue; }
  const d = parseDate(p.date_shared);
  if (d && d >= '2026-09-07' && d <= TODAY) { const k = who(p); sentThisWeek[k] = (sentThisWeek[k] || 0) + 1; }
}

// queued = not sent, not paused, active startup
const rows = []; const q = {};
for (const p of pipe) {
  if (s(p.deal_shared).toLowerCase() === 'yes' || s(p.pause).toLowerCase() === 'yes') { continue; }
  const st = s(p.startup); if (!active[st]) { continue; }
  if (!p.row_number) { throw new Error('ABORT: row without row_number'); }
  const owner = s(p.owner) || active[st];
  const r = { rn: p.row_number, st: st, owner: owner, inbox: who(p), pri: parseFloat(s(p.priority)) || 0,
    old: parseDate(p.next_due) || '', oldRaw: s(p.next_due), deal: s(p.deal_id), nd: null };
  rows.push(r);
  if (!q[owner]) { q[owner] = {}; } if (!q[owner][st]) { q[owner][st] = []; } q[owner][st].push(r);
}
for (const o of Object.keys(q)) { for (const st of Object.keys(q[o])) {
  q[o][st].sort(function (a, b) { return b.pri - a.pri || (a.old < b.old ? -1 : (a.old > b.old ? 1 : 0)); }); } }

const days = []; { const d = new Date(Date.UTC(2026, 8, 11)); while (days.length < 400) { const w = d.getUTCDay(); if (w !== 0 && w !== 6) { days.push(d.toISOString().slice(0, 10)); } d.setUTCDate(d.getUTCDate() + 1); } }
function dow(ds) { return new Date(ds + 'T00:00:00Z').getUTCDay(); }

let invWeek = Object.assign({}, sentThisWeek); let assigned = 0;
for (let di = 0; di < days.length && assigned < rows.length; di++) {
  const day = days[di];
  if (di > 0 && dow(day) === 1) { invWeek = {}; }
  const invDay = {};
  for (const o of Object.keys(q)) {
    const sts = Object.keys(q[o]).filter(function (st) { return q[o][st].length; }).sort();
    if (!sts.length) { continue; }
    const off = di % sts.length;
    const order = sts.slice(off).concat(sts.slice(0, off));   // rotate so no startup always goes first
    let cap = OWNER_CAP; let progress = true;
    while (cap > 0 && progress) {
      progress = false;
      for (const st of order) {
        if (cap === 0) { break; }
        const list = q[o][st];
        for (let i = 0; i < list.length; i++) {
          const r = list[i];
          if ((invWeek[r.inbox] || 0) >= WEEK_CAP || (invDay[r.inbox] || 0) >= DAY_CAP) { continue; }
          r.nd = day; list.splice(i, 1);
          invWeek[r.inbox] = (invWeek[r.inbox] || 0) + 1; invDay[r.inbox] = (invDay[r.inbox] || 0) + 1;
          cap--; assigned++; progress = true; break;
        }
      }
    }
  }
}
if (assigned < rows.length) { throw new Error('ABORT: could only place ' + assigned + ' of ' + rows.length + ' rows within 400 weekdays'); }

// ---- verify every rule before writing anything ----
function weekKey(ds) { const d = new Date(ds + 'T00:00:00Z'); const w = d.getUTCDay(); d.setUTCDate(d.getUTCDate() - (w === 0 ? 6 : w - 1)); return d.toISOString().slice(0, 10); }
const iw = {}, idd = {}, od = {};
for (const k of Object.keys(sentThisWeek)) { iw[k + '|2026-09-07'] = sentThisWeek[k]; }
for (const r of rows) {
  const a = r.inbox + '|' + weekKey(r.nd); iw[a] = (iw[a] || 0) + 1;
  const b = r.inbox + '|' + r.nd; idd[b] = (idd[b] || 0) + 1;
  const c = r.owner + '|' + r.nd; od[c] = (od[c] || 0) + 1;
}
let maxWeek = 0, maxDay = 0, maxOwner = 0; let worstWeek = '';
for (const k of Object.keys(iw)) { if (iw[k] > maxWeek) { maxWeek = iw[k]; worstWeek = k; } }
for (const k of Object.keys(idd)) { if (idd[k] > maxDay) { maxDay = idd[k]; } }
for (const k of Object.keys(od)) { if (od[k] > maxOwner) { maxOwner = od[k]; } }
// already-sent deals this week can exceed 5 on their own (e.g. 10 today) - only new placements must respect the cap
let newOverCap = 0;
for (const k of Object.keys(iw)) { const parts = k.split('|'); const already = parts[1] === '2026-09-07' ? (sentThisWeek[parts[0]] || 0) : 0;
  if (iw[k] > WEEK_CAP && iw[k] > already) { newOverCap++; } }
if (newOverCap) { throw new Error('ABORT: ' + newOverCap + ' inbox-weeks would exceed the cap of ' + WEEK_CAP); }
if (maxDay > DAY_CAP) { throw new Error('ABORT: an inbox would get ' + maxDay + ' in one day'); }
if (maxOwner > OWNER_CAP) { throw new Error('ABORT: a mailbox would send ' + maxOwner + ' in one day'); }

const changes = rows.filter(function (r) { return r.nd !== r.old; });
if (changes.length > 3600) { throw new Error('ABORT: ' + changes.length + ' changes exceeds guard of 3600'); }
if (!changes.length) { throw new Error('NOTHING TO DO'); }

// ---- summary per week and per startup ----
const weekTot = {}; const perSt = {};
for (const r of rows) {
  const wk = weekKey(r.nd); weekTot[wk] = (weekTot[wk] || 0) + 1;
  if (!perSt[r.st]) { perSt[r.st] = { days: {}, weeks: {}, n: 0 }; }
  perSt[r.st].days[r.nd] = 1; perSt[r.st].weeks[wk] = (perSt[r.st].weeks[wk] || 0) + 1; perSt[r.st].n++;
}
const dayIndex = {}; days.forEach(function (d, i) { dayIndex[d] = i; });
const stSummary = Object.keys(perSt).sort().map(function (st) {
  const ds = Object.keys(perSt[st].days).sort(); let gap = dayIndex[ds[0]];
  for (let i = 1; i < ds.length; i++) { const g = dayIndex[ds[i]] - dayIndex[ds[i - 1]] - 1; if (g > gap) { gap = g; } }
  const wks = Object.keys(perSt[st].weeks).sort();
  return [st, perSt[st].n, ds[0], ds[ds.length - 1], gap, wks.slice(0, 4).map(function (w) { return perSt[st].weeks[w]; }).join('/')];
});
const weeksSorted = Object.keys(weekTot).sort();
return [{ json: {
  next_due_column: L, queued_rows: rows.length, rows_changed: changes.length, rows_unchanged: rows.length - changes.length,
  first_date: days[0], last_date: rows.reduce(function (m, r) { return r.nd > m ? r.nd : m; }, ''),
  weeks_to_send_queue: weeksSorted.length,
  per_week_totals: weeksSorted.map(function (w) { return w + ': ' + weekTot[w]; }),
  checks: { max_new_per_inbox_per_week: WEEK_CAP, inbox_weeks_over_cap_from_new: newOverCap, max_inbox_per_day: maxDay, max_mailbox_per_day: maxOwner,
    heaviest_inbox_week: worstWeek + ' = ' + maxWeek + ' (includes deals already sent this week)' },
  startup_cols: ['startup', 'queued', 'first_date', 'last_date', 'longest_idle_weekdays', 'deals_weeks_1_4'],
  startups: stSummary,
  backup_cols: ['row_number', 'deal_id', 'old_next_due', 'new_next_due'],
  backup: changes.map(function (r) { return [r.rn, r.deal, r.oldRaw, r.nd]; }),
  data: changes.map(function (r) { return { range: 'PIPELINE!' + L + r.rn, values: [[r.nd]] }; })
} }];
